173:     description: template.description,
174:     targets: template.targets.map((t, idx) => ({
175:       id: `target-${localDate}-${idx}`,
176:       kind: t.kind,
177:       count: t.count,
178:       label: t.label,
179:     })),
180:   };
181: }
